    if ($StrictDesktop) { Write-FailMsg $msg } else { Write-WarnMsg $msg }
  }
} catch {
  $msg = 'Cannot reach 127.0.0.1:3845 - enable Dev Mode MCP in Figma Desktop'
  if ($StrictDesktop) { Write-FailMsg $msg } else { Write-WarnMsg $msg }
}

input.new_string:
